import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../../assets";
import { ISpiderExposedState, ISpiderStackMap } from "../../../../common";

interface IProps {
  scene: Phaser.Scene;
  builder: ViewElementBuilder;
  stackMap: ISpiderStackMap;
  offsetY?: number;
}

export class SpiderStackCountInfo {
  private readonly stockLabel: Phaser.GameObjects.Text;
  private readonly tableauLabels: Phaser.GameObjects.Text[];
  private readonly align = new Align();
  private readonly offsetY: number;

  constructor(private readonly props: IProps) {
    const { builder, stackMap } = props;

    this.offsetY = props.offsetY ?? -6;
    this.stockLabel = builder.deckCountInfo("0");
    this.tableauLabels = stackMap.tableaus.map(() => builder.deckCountInfo("0 / 0"));

    this.layoutLabels();
  }

  update(state: ISpiderExposedState) {
    this.stockLabel.setText(`${state.stockCount}`);
    state.tableauCounts.forEach((count, index) => {
      const label = this.tableauLabels[index];
      if (!label) return;
      label.setText(`${count.closed} / ${count.open}`);
    });
    this.layoutLabels();
  }

  destroy() {
    this.stockLabel.destroy();
    this.tableauLabels.forEach((label) => label.destroy());
  }

  private layoutLabels() {
    const { stackMap } = this.props;

    this.align.anchor(stackMap.stock.cardPlace).topTo(this.stockLabel, this.offsetY).centerX(this.stockLabel);
    stackMap.tableaus.forEach((tableau, index) => {
      const label = this.tableauLabels[index];
      if (!label) return;
      this.align.anchor(tableau.cardPlace).topTo(label, this.offsetY).centerX(label);
    });
  }
}
