import { GameServicePlayerData } from "../types";
import { getUrlParam, isAllowedHost } from "../../../common";

export function getCheatPlayerData(): Partial<GameServicePlayerData> | undefined {
  if(!isAllowedHost(["localhost", "kvisaz.github.io"])) return;

  return getMegaBonusData('iddqd') ?? getZeroBonusData('zero');
}


function getMegaBonusData(cheat:string): Partial<GameServicePlayerData> | undefined {
  const isCheatEnabled = getUrlParam(cheat);

  if (!isCheatEnabled) return;

  return {
    consumables: {
      UNDO: 999,
      HINT: 999,
      VISION: 999,
      MAGIC: 999
    }
  };
}

function getZeroBonusData(cheat:string): Partial<GameServicePlayerData> | undefined {
  const isCheatEnabled = getUrlParam(cheat);

  if (!isCheatEnabled) return;

  return {
    consumables: {
      UNDO: 0,
      HINT: 0,
      VISION: 0,
      MAGIC: 0
    }
  };
}
