  /** switchButtons **/
  buttonSwitchMusic(onSwitchClick: (isOn: boolean) => void, textProps?: ITextBuildProps) {
    const imageAssetOn = AssetsConfig.images.uiSwitchMusicOn;
    const textOn = getLocalizedText("settings.music.on");

    const imageAssetOff = AssetsConfig.images.uiSwitchMusicOff;
    const textOff = getLocalizedText("settings.music.off");

    return this.buttonSwitch({
      imageAssetOn,
      textOn,
      imageAssetOff,
      textOff,
      onSwitchClick,
      textProps,
    });
  }

  buttonSwitchSound(onSwitchClick: (isOn: boolean) => void, textProps?: ITextBuildProps) {
    const imageAssetOn = AssetsConfig.images.uiSwitchSoundOn;
    const textOn = getLocalizedText("settings.sound.on");

    const imageAssetOff = AssetsConfig.images.uiSwitchSoundOff;
    const textOff = getLocalizedText("settings.sound.off");

    return this.buttonSwitch({
      imageAssetOn,
      textOn,
      imageAssetOff,
      textOff,
      onSwitchClick,
      textProps,
    });
  }

  protected buttonSwitch(args: {
    imageAssetOn: ImageAsset;
    textOn: string;
    imageAssetOff: ImageAsset;
    textOff: string;
    onSwitchClick: (to: boolean) => void;
    textProps?: ITextBuildProps;
  }) {
    const textStyle: ITextBuildProps = {
      fontSize: "32px",
      weight: "semibold",
      color: "#485743",
      ...args.textProps,
    };
    const textOffAlpha = 0.8;
    const padding = 16;

    const { scene } = this;

    const makeBg = () => new Phaser.GameObjects.Rectangle(scene, 0, 0, 390, 150, 0x00000000, 0);

    const bgOn = makeBg();
    const imageOn = this.image(args.imageAssetOn);
    const textOn = this.textMain(args.textOn, textStyle);

    const bgOff = makeBg();
    const imageOff = this.image(args.imageAssetOff);
    const textOff = this.textMain(args.textOff, textStyle).setAlpha(textOffAlpha);

    const { align } = this;
    align.anchor(bgOn).centerY(imageOn).leftIn(imageOn, 8);
    align.anchor(imageOn).rightTo(textOn, padding).centerY(textOn);

    align.anchor(bgOff).centerY(imageOff).leftIn(imageOff, 8);
    align.anchor(imageOff).rightTo(textOff, padding).centerY(textOff);

    return this.addButtonSound(
      new SwitchButton({
        viewOn: new Phaser.GameObjects.Container(scene, 0, 0, [bgOn, imageOn, textOn]),
        viewOff: new Phaser.GameObjects.Container(scene, 0, 0, [bgOff, imageOff, textOff]),
        onSwitchClick: (to) => {
          args.onSwitchClick(to);
        },
        options: {
          once: false,
        },
      }),
    );
  }

