import { Align, AlignObject } from "@kvisaz/phaser-sugar";
import { OverlayScene } from "../../../../../common/scenes";
import { ViewElementBuilder } from "../../../../../assets";
import { GameServiceProvider } from "../../../../../services";
import { TypedEventsEmitter } from "../../../../../common";
import { IGameLogicCommandEvents, IGameViewEvents } from "../../../logic";
import { FullscreenOverlay } from "../../../../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
  commands: TypedEventsEmitter<IGameLogicCommandEvents>;
  viewEvents: TypedEventsEmitter<IGameViewEvents>;
}

export class CommonAdsOverlay {
  private readonly builder: ViewElementBuilder;
  private readonly overlayScene: Phaser.Scene;
  private overlay?: FullscreenOverlay;
  private closeButton?: Phaser.GameObjects.GameObject & AlignObject;
  private busy = false;
  private unSubs: Array<() => void> = [];

  constructor(private props: IProps) {
    OverlayScene.attach(props.scene);
    this.overlayScene = OverlayScene.get(props.scene);
    this.builder = new ViewElementBuilder(this.overlayScene);
    this.subscribe();
  }

  destroy() {
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
    this.destroyOverlay();
  }

  private subscribe() {
    this.unSubs.push(this.props.commands.on("showCommonAd", () => this.showCommonAd()));
  }

  private showCommonAd() {
    if (this.busy) return;
    this.busy = true;
    this.pauseSound();
    this.createOverlay();
    GameServiceProvider.get().showCommonAd((args) => this.finish(args));
  }

  private finish(args: { wasShown: boolean; error?: string }) {
    this.destroyOverlay();
    this.props.viewEvents.emit("onCommonAdClose", args);
    this.resumeSound();
    this.busy = false;
  }

  private createOverlay() {
    this.destroyOverlay();
    const scene = this.overlayScene;

    this.overlay = new FullscreenOverlay({ scene, interactive: true });
    this.closeButton = this.builder.buttonCloseCross(() => {
      this.finish({ wasShown: false });
    });
    const align = new Align();
    align
      .anchorSceneScreen(scene)
      .rightIn(this.closeButton, -24)
      .topIn(this.closeButton, 24);
    scene.add.existing(this.closeButton);
  }

  private pauseSound() {
    this.props.scene.sound.pauseAll();
  }

  private resumeSound() {
    this.props.scene.sound.resumeAll();
  }

  private destroyOverlay() {
    this.closeButton?.destroy();
    this.overlay?.destroy();
    this.closeButton = undefined;
    this.overlay = undefined;
  }
}
