import { InAppPurchaseId, RewardPurchaseId } from "./types";

const rewardPurchaseIdSet = new Set<RewardPurchaseId>([
  "undoPack",
  "hintPack",
  "magicPack",
  "visionPack",
]);

export function isRewardPurchaseId(value: unknown): value is RewardPurchaseId {
  return typeof value === "string" && rewardPurchaseIdSet.has(value as RewardPurchaseId);
}

const inAppPurchaseIdSet = new Set<InAppPurchaseId>([
  "common",
  "gold",
  "silver"
]);

export function isInAppPurchaseId(value: unknown): value is InAppPurchaseId {
  return typeof value === "string" && inAppPurchaseIdSet.has(value as InAppPurchaseId);
}
