import { AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { createGO, Observable, TypedEventsEmitter } from "../../../../common";
import { ViewElementBuilder } from "../../../../assets";
import { GameLogicState, IGameViewEvents } from "../../logic";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<GameLogicState>;
  gameSceneViewEvents: TypedEventsEmitter<IGameViewEvents>;
}

export class UiButtonsSideBar extends Phaser.GameObjects.Container {
  constructor(private props: IProps) {
    super(props.scene);
    const buttons = this.createButtons();

    layoutChain({
      children: buttons,
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 20,
      alignToAnchor: AlignMethod.LEFT_IN,
    });
    this.add(buttons);
    this.scene.add.existing(this);
  }

  private createButtons() {
    const { scene, gameState, gameSceneViewEvents } = this.props;

    const builder = new ViewElementBuilder(scene);

    const buttons = [
      createGO(() => builder.buttonNewGame(()=>gameSceneViewEvents.emit('uiNewGameClick'))),
      createGO(() => builder.buttonReplayGame(()=>gameSceneViewEvents.emit('uiReplayClick'))),
      createGO(() => builder.buttonUndo(()=>gameSceneViewEvents.emit('uiUndoClick')), {
        use: (button) => {
          gameState.on((state) => {
            button.enable(state.consumableButtonsEnabled.UNDO);
            button.setAmount(state.consumableBalance.UNDO);
            button.rewardIconEnable(
              button.isEnabled && state.consumableBalance.UNDO === 0
            );
          });
          button.enable(gameState.getState().consumableButtonsEnabled.UNDO);
          button.setAmount(gameState.getState().consumableBalance.UNDO);
        },
      }),
      createGO(() => builder.buttonHint(()=>gameSceneViewEvents.emit('uiHintClick')), {
        use: (button) => {
          gameState.on((state) => {
            button.enable(state.consumableButtonsEnabled.HINT);
            button.setAmount(state.consumableBalance.HINT);
            button.rewardIconEnable(
              button.isEnabled && state.consumableBalance.HINT === 0);
          });
          button.enable(gameState.getState().consumableButtonsEnabled.HINT);
          button.setAmount(gameState.getState().consumableBalance.HINT);
        },
      }),
      createGO(() => builder.buttonVision(()=>gameSceneViewEvents.emit('uiVisionClick')), {
        use: (button) => {
          gameState.on((state) => {
            button.enable(state.consumableButtonsEnabled.VISION);
            button.setAmount(state.consumableBalance.VISION);
            button.rewardIconEnable(
              button.isEnabled && state.consumableBalance.VISION === 0);
          });
          button.enable(gameState.getState().consumableButtonsEnabled.VISION);
          button.setAmount(gameState.getState().consumableBalance.VISION);
        },
      }),
      createGO(() => builder.buttonMagic(()=>gameSceneViewEvents.emit('uiMagicClick')), {
        use: (button) => {
          gameState.on((state) => {
            button.enable(state.consumableButtonsEnabled.MAGIC);
            button.setAmount(state.consumableBalance.MAGIC);
            button.rewardIconEnable(
              button.isEnabled && state.consumableBalance.MAGIC === 0);
          });
          button.enable(gameState.getState().consumableButtonsEnabled.MAGIC);
          button.setAmount(gameState.getState().consumableBalance.MAGIC);
        },
      }),
    ];

    return buttons;
  }
}
