import { GameServicePlayerData } from "../types";

export const mergePlayerData = (
  target: GameServicePlayerData,
  options: Partial<GameServicePlayerData> = {},
): GameServicePlayerData => {

  return {
    settings: {
      ...target.settings,
      ...options.settings,
    },
    consumables: {
      ...target.consumables,
      ...options.consumables
    }
  }
};
