import { Align, AlignMethod, AlignObject, layoutChain } from "@kvisaz/phaser-sugar";
import { ConsumableType, ILogicShopItem, mapConsumableShopPackToArray } from "../../logic";
import { getConsumableSortOrder, getSafeNumber } from "../../common";
import { getLocalizedText } from "../locale";
import { ITextButtonOptions } from "../builders/ViewElementBuilder/types";

type Child = AlignObject & Phaser.GameObjects.GameObject;

interface IProps {
  scene: Phaser.Scene;
  item: ILogicShopItem;
  frameBuilder: (width: number, height: number) => Child;
  iconBuilder: (consumableType: ConsumableType) => Child;
  videoPlayIconBuilder: () => Child;
  textShopItemLabel(text: string): Phaser.GameObjects.Text;
  buttonBuilder: (text: string, options?: ITextButtonOptions) => Phaser.GameObjects.Container;
}

export class ShopItemView extends Phaser.GameObjects.Container {
  constructor(private props: IProps) {
    super(props.scene, 0, 0);

    const { scene, item, frameBuilder, videoPlayIconBuilder, buttonBuilder } = props;

    const { price, currency, rewardAdPrice: isReward } = item;
    const safePrice = getSafeNumber(price);
    const priceLabel =
      safePrice === 0
        ? getLocalizedText("shop.free").toUpperCase()
        : `${safePrice} ${currency}`.trim();

    const externalPadding = 12;
    const buttonTopPadding = isReward ? 11 : 20;
    const bottomPadding = isReward ? 12 : 14;

    /** Блок иконок и их числа **/
    const content = this.getContent();

    /** текст кнопки **/
    const align = new Align();

    /** Кнопка покупки **/
    const fontSizePx = isReward ? 32 : 40;
    const buttonWidth = 240;
    const buyButton = buttonBuilder(priceLabel, {
      fontSizePx,
      width: buttonWidth,
    });
    align.anchor(buyButton).centerX(content).topTo(content, -buttonTopPadding);

    /** иконка видео покупки **/
    const playIcon = isReward ? videoPlayIconBuilder() : undefined;
    if (playIcon) {
      align.anchor(buyButton).centerY(playIcon).rightTo(playIcon, -20);
      buyButton.add(playIcon);
    }

    /** враппер очередного контента  **/
    const contentContainer = new Phaser.GameObjects.Container(scene, 0, 0, [content, buyButton]);
    const contentBounds = contentContainer.getBounds();

    /** frame **/
    const width = contentBounds.width + externalPadding * 2;
    const height = contentBounds.height + externalPadding * 2;
    const bg = frameBuilder(width, height);
    align.anchor(bg).center(contentContainer).bottomIn(contentContainer, -bottomPadding);

    this.add([bg, contentContainer]);
  }

  get shopItem(){
    return this.props.item;
  }

  private getContent(): Phaser.GameObjects.Container {
    const { scene, item, iconBuilder, textShopItemLabel } = this.props;
    const layoutContainer = new Phaser.GameObjects.Container(scene, 0, 0);

    const consumables =
      item.shopPack.type === "consumables"
        ? mapConsumableShopPackToArray(item.shopPack).sort(
            (a, b) => getConsumableSortOrder(a.type) - getConsumableSortOrder(b.type),
          )
        : undefined;

    if (consumables == null) return layoutContainer;

    /**  иконки и числа в ряд **/
    const rows = consumables.map((c) => {
      const icon = iconBuilder(c.type);
      const text = textShopItemLabel(`+${c.amount}`);
      layoutContainer.add([icon, text]);
      const row = layoutChain({
        children: [icon, text],
        alignToNext: AlignMethod.RIGHT_TO,
        nextOffsetX: 12,
        alignToAnchor: AlignMethod.CENTER_Y,
      });
      return row;
    });

    /** выравнивание в колонку **/
    layoutChain({
      children: rows,
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 12,
      alignToAnchor: AlignMethod.LEFT_IN,
    });

    return layoutContainer;
  }
}
